package com.xyz.question_bank_management_system.security;
import jakarta.servlet.*;import jakarta.servlet.http.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.security.core.authority.SimpleGrantedAuthority;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.stereotype.Component;import org.springframework.util.StringUtils;import org.springframework.web.filter.OncePerRequestFilter;import java.io.IOException;import java.util.List;
@Component public class InternalServiceAuthenticationFilter extends OncePerRequestFilter {@Value("${app.internal-api.token:}")private String token;@Override protected boolean shouldNotFilter(HttpServletRequest request){return !request.getRequestURI().startsWith("/internal/v1/");}@Override protected void doFilterInternal(HttpServletRequest request,HttpServletResponse response,FilterChain chain)throws ServletException,IOException{String supplied=request.getHeader("X-Internal-Token");if(StringUtils.hasText(token)&&constantTimeEquals(token,supplied)){var auth=new UsernamePasswordAuthenticationToken("internal-service",null,List.of(new SimpleGrantedAuthority("INTERNAL_SERVICE")));SecurityContextHolder.getContext().setAuthentication(auth);}chain.doFilter(request,response);}private boolean constantTimeEquals(String expected,String actual){if(actual==null||expected.length()!=actual.length())return false;int diff=0;for(int i=0;i<expected.length();i++)diff|=expected.charAt(i)^actual.charAt(i);return diff==0;}}
